    'Tests.csproj': {'xunit': '2.9.3', 'System.Text.Json': '10.0.1'},
    'Worker.csproj': {'Microsoft.Extensions.Hosting': '8.0.1', 'OpenTelemetry.Extensions.Hosting': '1.15.0', 'System.Text.Json': '10.0.1'}
}
changes = []
unchanged = []
